input.content:
@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
	html {
		scroll-behavior: smooth;
	}

	body {
		@apply bg-white text-secondary-900;
	}
}

@layer components {
	.btn-primary {
		@apply inline-flex items-center justify-center px-6 py-3 text-base font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-700 transition-colors shadow-lg;
	}

	.btn-secondary {
		@apply inline-flex items-center justify-center px-6 py-3 text-base font-medium text-primary-600 bg-primary-50 rounded-lg hover:bg-primary-100 transition-colors border border-primary-200;
	}

	.card {
		@apply bg-white rounded-xl border border-secondary-200 hover:shadow-xl transition-all duration-300;
	}

	.card-hover {
		@apply hover:border-primary-300 hover:shadow-xl transition-all duration-300;
	}
}

/* Custom animations */
@keyframes fadeIn {
	from {
		opacity: 0;
		transform: translateY(20px);
	}
	to {
		opacity: 1;
		transform: translateY(0);
	}
}

.animate-fade-in {
	animation: fadeIn 0.6s ease-out;
}

/* Focus styles for accessibility */
.focus-ring {
	@apply focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2;
}

/* Smooth transitions */
.transition-smooth {
	@apply transition-all duration-300 ease-in-out;
}

/* Custom scrollbar */
::-webkit-scrollbar {
	width: 8px;
}

::-webkit-scrollbar-track {
	@apply bg-secondary-100;
}

::-webkit-scrollbar-thumb {
	@apply bg-secondary-300 rounded-full;
}

::-webkit-scrollbar-thumb:hover {
	@apply bg-secondary-400;
}
